mapper.update:
update t_tran
set customer_id = NULL
where customer_id = #{customerId,jdbcType=INTEGER}

mapper.select:
select tt.*, tdv.id stageId, tdv.type_value stageName, tu.id createById, tu.name createByName, tc2.full_name as customerName from t_tran tt left join t_dic_value tdv on tt.stage = tdv.id left join t_user tu on tt.create_by = tu.id left join t_customer tcu on tt.customer_id = tcu.id left join t_clue tc2 on tcu.clue_id = tc2.id
and tt.customer_id = #{customerId,jdbcType=INTEGER}
and tt.money = #{money,jdbcType=DECIMAL}
order by tt.create_time desc

select tt.*, tdv.id stageId, tdv.type_value stageName, tc2.full_name as customerName from t_tran tt left join t_dic_value tdv on tt.stage = tdv.id left join t_customer tcu on tt.customer_id = tcu.id left join t_clue tc2 on tcu.clue_id = tc2.id
tt.create_by = #{createBy,jdbcType=INTEGER}
and tt.stage = #{stage,jdbcType=INTEGER}
order by tt.create_time desc limit #{limit}

select tt.*, tdv.id stageId, tdv.type_value stageName, tu.id createById, tu.name createByName, tc2.full_name as customerName from t_tran tt left join t_dic_value tdv on tt.stage = tdv.id left join t_user tu on tt.create_by = tu.id left join t_customer tcu on tt.customer_id = tcu.id left join t_clue tc2 on tcu.clue_id = tc2.id
and tc2.full_name like concat('%', #{customerName,jdbcType=VARCHAR}, '%')
and tt.stage = #{stage,jdbcType=INTEGER}
order by tt.create_time desc limit #{limit}
